export function reliability(add,cpp){
const index="struct Index {\n    std::vector<std::vector<int>> leaves{{}};\n    std::size_t route(int key) const {\n        std::size_t at = 0;\n        while (at + 1 < leaves.size() && key >= leaves[at + 1].front())\n            ++at;\n        return at;\n    }\n    bool contains(int key) const {\n        const auto &leaf = leaves[route(key)];\n        return std::binary_search(leaf.begin(), leaf.end(), key);\n    }\n    bool insert(int key) {\n        auto at = route(key);\n        if (contains(key))\n            return false;\n        if (leaves[at].size() == 4 && leaves.size() == 8)\n            return false;\n        auto candidate = leaves;\n        auto &leaf = candidate[at];\n        leaf.insert(std::lower_bound(leaf.begin(), leaf.end(), key), key);\n        if (leaf.size() > 4) {\n            std::vector<int> right(leaf.begin() + 2, leaf.end());\n            leaf.erase(leaf.begin() + 2, leaf.end());\n            candidate.insert(candidate.begin() + static_cast<std::ptrdiff_t>(at + 1),\n                             std::move(right));\n        }\n        leaves.swap(candidate);\n        return true;\n    }\n    bool erase(int key) {\n        auto at = route(key);\n        if (!contains(key))\n            return false;\n        auto candidate = leaves;\n        auto &leaf = candidate[at];\n        leaf.erase(std::lower_bound(leaf.begin(), leaf.end(), key));\n        if (leaf.size() < 2 && candidate.size() > 1) {\n            if (at > 0 && candidate[at - 1].size() > 2) {\n                leaf.insert(leaf.begin(), candidate[at - 1].back());\n                candidate[at - 1].pop_back();\n            } else if (at + 1 < candidate.size() && candidate[at + 1].size() > 2) {\n                leaf.push_back(candidate[at + 1].front());\n                candidate[at + 1].erase(candidate[at + 1].begin());\n            } else if (at > 0) {\n                auto &left = candidate[at - 1];\n                left.insert(left.end(), leaf.begin(), leaf.end());\n                candidate.erase(candidate.begin() + static_cast<std::ptrdiff_t>(at));\n            } else {\n                leaf.insert(leaf.end(), candidate[1].begin(), candidate[1].end());\n                candidate.erase(candidate.begin() + 1);\n            }\n        }\n        leaves.swap(candidate);\n        return true;\n    }\n    std::vector<int> range(int low, int high) const {\n        std::vector<int> result;\n        for (const auto &leaf : leaves)\n            for (int key : leaf)\n                if (key >= low && key < high)\n                    result.push_back(key);\n        return result;\n    }\n    bool valid() const {\n        if (leaves.empty() || leaves.size() > 8)\n            return false;\n        std::optional<int> previous;\n        for (const auto &leaf : leaves) {\n            if (leaf.size() > 4 || (leaves.size() > 1 && leaf.size() < 2))\n                return false;\n            for (int key : leaf) {\n                if (previous && *previous >= key)\n                    return false;\n                previous = key;\n            }\n        }\n        return true;\n    }\n};";
const ih='algorithm cstddef iostream optional set utility vector';
add('bplus-tree','bplus-routing','Route a key through leaf separator values',
'A B+ index keeps payload keys in leaves and uses separator values to choose a leaf. This bounded model has one routing root and at most eight four-key leaves; separators are derived from each right leaf’s first key.\n\nIt is not an arbitrary-height serialized B+ tree. Value-owned leaf vectors make structural ownership explicit while the lessons focus on routing and occupancy.',
cpp(ih,"    Index tree;\n    for (int key : {1, 2, 3, 4, 5})\n        tree.insert(key);\n    std::cout << \"leaves=\" << tree.leaves.size() << \" route2=\" << tree.route(2)\n              << \" route3=\" << tree.route(3) << \"\\n\";",index),'leaves=2 route2=0 route3=1',
'After the first split, key three is the right leaf’s separator. Equal keys route right to the leaf that actually stores them.',
'A separator equality rule inconsistent with insertion can make stored keys unreachable.',
['Where does a key equal to the right leaf’s separator route?','To that right leaf','Always to the left leaf','To no leaf'],'The separator is the minimum key of the right leaf in this model.',
'Check keys below all entries, exactly at separators, between keys, and above all entries after several splits.');
add('bplus-tree','bplus-split','Split an overflowing leaf before publishing structure',
'A leaf split redistributes an overflowing sorted key sequence into two leaves and adds a routing boundary. Here five keys split into two on the left and three on the right.\n\nInsertion prepares a complete candidate leaf collection before swapping it into the live index. Allocation failure during preparation therefore does not partially publish the new routing structure.',
cpp(ih,"    Index tree;\n    for (int key : {1, 2, 3, 4, 5})\n        tree.insert(key);\n    std::cout << tree.leaves[0].size() << \" \" << tree.leaves[1].size()\n              << \" valid=\" << tree.valid() << \"\\n\";",index),'2 3 valid=1',
'Both resulting leaves fit the four-key maximum and the two-key non-root minimum.',
'Updating a separator before installing its new leaf can expose an inconsistent index.',
['What is prepared before the live swap?','The complete candidate leaf collection','Only the printed separator','A raw pointer to a temporary leaf'],'Fallible structural preparation is separate from publication.',
'Insert at the beginning, middle, and end of a full leaf. Verify the complete key sequence and occupancy after each split.');
add('bplus-tree','bplus-range','A range query crosses leaf boundaries',
'A B+ range query starts at the appropriate lower boundary and continues through ordered leaves until the exclusive upper boundary. This model stores leaf order in the owning vector rather than a serialized sibling chain.\n\nThe query contract uses [low,high), which makes adjacent ranges composable without returning a boundary key twice.',
cpp(ih,"    Index tree;\n    for (int key = 1; key <= 9; ++key)\n        tree.insert(key);\n    for (int key : tree.range(3, 8))\n        std::cout << key;\n    std::cout << \"\\n\";",index),'34567',
'The query returns keys three through seven across several leaves, excluding eight.',
'Stopping at the first leaf boundary loses valid matches in later leaves.',
['Is the upper key eight included?','No','Yes','Only if it is a separator'],'The result contract is a half-open key interval.',
'Test an empty range, a missing lower key, and boundaries exactly on separators. Compare with a std::set range.');
add('bplus-tree','bplus-rejection','Reject duplicates and bounded-root exhaustion without mutation',
'An index needs explicit failure behavior for duplicate keys and for its supported structural capacity. This model rejects an insertion that would require a ninth root child. Its maximum usable key count depends on leaf occupancy, not just four times the number of leaves.\n\nBoth rejection checks occur before copying or mutating live leaves.',
cpp(ih,"    Index tree;\n    for (int key = 1; key <= 18; ++key)\n        tree.insert(key);\n    auto before = tree.leaves;\n    bool duplicate = !tree.insert(1), bounded = !tree.insert(19);\n    std::cout << \"duplicate=\" << duplicate << \" bounded=\" << bounded\n              << \" preserved=\" << (before == tree.leaves) << \"\\n\";",index),'duplicate=1 bounded=1 preserved=1',
'Sequential insertion has already produced eight leaves. Splitting the final full leaf would exceed the root contract, so the saved representation remains unchanged.',
'Calling a bounded two-level model a production arbitrary-height tree conceals a critical capacity limit.',
['What must rejection preserve?','The existing keys and routing state','Only the root address','Nothing if a message is printed'],'An unsuccessful operation must retain the promised valid index state.',
'Try different insertion orders and record where the root limit is reached. Verify every earlier key remains searchable after rejection.');
add('bplus-tree','bplus-borrow','Borrow from a sibling with spare occupancy',
'Deletion can leave a non-root leaf below its minimum occupancy. If an adjacent sibling has more than the minimum, a boundary key can move across while retaining global ordering. The routing separator must reflect the new boundary.\n\nDerived separators in this model update automatically from the current leaf contents.',
cpp(ih,"    Index tree;\n    for (int key = 1; key <= 5; ++key)\n        tree.insert(key);\n    tree.erase(1);\n    std::cout << \"left=\" << tree.leaves[0].front() << \",\" << tree.leaves[0].back()\n              << \" right=\" << tree.leaves[1].front() << \" valid=\" << tree.valid()\n              << \"\\n\";",index),'left=2,3 right=4 valid=1',
'The right sibling gives key three to the underfull left leaf. Its new first key becomes four.',
'Borrowing from a minimum-sized sibling simply transfers the occupancy violation.',
['When can a sibling donate?','When it has more than the minimum occupancy','Whenever it exists','Only when it is empty'],'Donation must leave both leaves valid.',
'Construct the mirrored left-sibling donation case and validate separator-equality searches after the borrow.');
add('bplus-tree','bplus-merge','Merge when neither sibling can donate',
'If an underfull leaf and its sibling fit together but the sibling cannot donate, merging removes a child from the routing root. Ownership of all surviving keys must transfer before the removed leaf representation disappears.\n\nThis bounded model merges value vectors in a candidate state, then publishes the complete result.',
cpp(ih,"    Index tree;\n    for (int key = 1; key <= 5; ++key)\n        tree.insert(key);\n    tree.erase(5);\n    tree.erase(1);\n    std::cout << \"leaves=\" << tree.leaves.size() << \" keys=\";\n    for (int key : tree.range(0, 10))\n        std::cout << key;\n    std::cout << \" valid=\" << tree.valid() << \"\\n\";",index),'leaves=1 keys=234 valid=1',
'After the first deletion both leaves are at minimum occupancy. The second deletion forces a merge into one three-key leaf.',
'Removing a root child without preserving all survivor keys can pass a simple occupancy check while losing data.',
['Why merge instead of borrowing in this fixture?','The sibling has no spare key','The deleted key was odd','Merging is required after every deletion'],'A minimum-sized sibling cannot donate without becoming invalid.',
'Compare the full pre/post key sets against an independent set after every borrow and merge sequence.');
add('bplus-tree','bplus-empty-root','Give the root an explicit empty-tree representation',
'Root occupancy rules differ from non-root leaf rules. A tree with no keys still needs a valid representation that supports future insertion and missing lookup. This model keeps one empty leaf under the bounded routing representation.\n\nDeletion of a missing key reports failure without changing the existing structure.',
cpp(ih,"    Index tree;\n    tree.insert(7);\n    tree.erase(7);\n    std::cout << \"leaves=\" << tree.leaves.size() << \" empty=\" << tree.leaves[0].empty()\n              << \" missing=\" << !tree.erase(7) << \" valid=\" << tree.valid() << \"\\n\";",index),'leaves=1 empty=1 missing=1 valid=1',
'Deleting the only key returns to the documented empty representation. The second deletion is a preserved-state failure.',
'Applying a non-root minimum occupancy rule to the empty root can make a valid empty tree impossible.',
['Is the single empty root leaf valid here?','Yes','No','Only until another lookup happens'],'The root has an explicitly different occupancy rule.',
'Alternate deleting the final key and reinserting a new key. Check empty lookup and range-query behavior each time.');
add('bplus-tree','bplus-reference','Check mixed updates against independent membership and structure',
'A reference ordered set supplies expected key membership and sorted traversal. Independent index checks supply occupancy, routing order, and root limits. Compare after every mutation so a short failing prefix identifies the first broken transition.\n\nThis finite workload verifies the bounded implementation on its fixtures; it is not a proof of arbitrary-height or disk recovery behavior.',
cpp(ih,"    Index tree;\n    std::set<int> model;\n    bool valid = true;\n    for (int key : {8, 1, 6, 2, 7, 3, 5, 4}) {\n        tree.insert(key);\n        model.insert(key);\n        valid = valid && tree.valid();\n    }\n    for (int key : {1, 6, 8, 3}) {\n        tree.erase(key);\n        model.erase(key);\n        valid = valid && tree.valid();\n    }\n    auto actual = tree.range(-100, 100);\n    std::vector<int> expected(model.begin(), model.end());\n    valid = valid && actual == expected;\n    std::cout << \"reference=\" << valid << \"\\n\";\n    return valid ? 0 : 1;",index),'reference=1',
'The independent set and bounded tree agree on all remaining keys while structural checks hold after each operation.',
'A traversal-only oracle may miss invalid occupancy that causes the next mutation to fail.',
['Which properties are checked separately?','Logical contents and structural invariants','Only serialized byte size','Only the newest inserted key'],'Representation validity and observable results are complementary checks.',
'Enumerate short insertion/deletion sequences and retain the smallest failing prefix. Add boundary and root-exhaustion cases separately.');

const tx="struct Transaction {\n    unsigned base;\n    std::map<int, int> rows;\n    bool active = true;\n};\nstruct Store {\n    unsigned revision = 0;\n    std::map<int, int> rows{{1, 10}, {2, 20}};\n    Transaction begin() const {\n        return {revision, rows, true};\n    }\n    bool commit(Transaction &transaction) {\n        if (!transaction.active || transaction.base != revision)\n            return false;\n        auto candidate = transaction.rows;\n        rows.swap(candidate);\n        ++revision;\n        transaction.active = false;\n        return true;\n    }\n};\nvoid rollback(Transaction &transaction) {\n    transaction.rows.clear();\n    transaction.active = false;\n}";
const th='iostream map stdexcept utility';
add('transactions','transaction-begin','Begin with a private candidate state',
'A transaction separates tentative writes from committed state. This teaching store copies a bounded map at begin so transaction-local changes cannot leak through shared mutable rows.\n\nIt is a serialized in-memory state model, not a concurrent implementation or a durable transaction engine. Later lessons add conflict and publication contracts.',
cpp(th,"    Store store;\n    auto transaction = store.begin();\n    transaction.rows.at(1) = 99;\n    std::cout << \"private=\" << transaction.rows.at(1)\n              << \" committed=\" << store.rows.at(1) << \"\\n\";",tx),'private=99 committed=10',
'The private map contains the new value while the committed map still contains the old value.',
'Copying only pointers to mutable rows would not isolate tentative writes.',
['Why are committed rows unchanged?','The transaction owns a separate candidate map','The output stream rolls back writes','All map copies share immutable storage'],'Owning value semantics separate the two mutable states.',
'Mutate several private rows and verify a second reader of committed state sees none of them before commit.');
add('transactions','read-own-writes','A transaction needs a coherent read view',
'A transaction usually reads its own writes even when other observers still see committed state. Its read interface must specify whether it consults a private candidate, an overlay, or a versioned snapshot.\n\nThis copy-based model reads directly from the candidate map. The representation is simple but incurs whole-table copying at begin.',
cpp(th,"    Store store;\n    auto transaction = store.begin();\n    transaction.rows[3] = 30;\n    std::cout << \"own=\" << transaction.rows.contains(3)\n              << \" external=\" << store.rows.contains(3) << \"\\n\";",tx),'own=1 external=0',
'The newly inserted key is visible inside the transaction and absent from the committed view.',
'Reading from committed state after writing a private overlay can hide a transaction’s own changes.',
['Which state supplies this transaction’s reads?','Its candidate map','Only the original committed map','Whichever map has fewer rows'],'The read view and tentative writes share one private state.',
'Model deletion and a repeated read of the same key. Document whether absence comes from the base state or a transaction-local deletion.');
add('transactions','transaction-commit','Publish a complete candidate at commit',
'Commit validates the transaction’s base revision, prepares the candidate copy, and publishes it with a nonthrowing map swap. All rows become visible through one serialized state transition.\n\nThis atomicity is a model of observable commit boundaries. It does not make unsynchronized threads safe to access the map concurrently.',
cpp(th,"    Store store;\n    auto transaction = store.begin();\n    transaction.rows.at(1) = 99;\n    std::cout << \"commit=\" << store.commit(transaction) << \" value=\" << store.rows.at(1)\n              << \" revision=\" << store.revision << \"\\n\";",tx),'commit=1 value=99 revision=1',
'A successful commit advances the revision and makes the transaction inactive.',
'Updating committed rows one by one can expose a partially committed batch to observers.',
['What publishes the prepared state?','The final map swap','Each private assignment','Printing a success message'],'Preparation and publication are separate operations.',
'Update two related rows and verify the committed view changes only at the commit boundary under a serialized test schedule.');
add('transactions','transaction-rollback','Rollback discards tentative ownership',
'Rollback ends a transaction without publishing its candidate. In this model, clearing the private map and marking it inactive releases tentative state while leaving the committed map alone.\n\nAn already rolled-back transaction must not be committed later. Transaction lifecycle state is part of the API, not a comment remembered only by callers.',
cpp(th,"    Store store;\n    auto transaction = store.begin();\n    transaction.rows.at(1) = 99;\n    rollback(transaction);\n    std::cout << \"value=\" << store.rows.at(1) << \" inactive=\" << !transaction.active\n              << \" commit=\" << store.commit(transaction) << \"\\n\";",tx),'value=10 inactive=1 commit=0',
'The original committed value remains ten, and the inactive candidate is rejected by commit.',
'A rollback that changes only a printed status but leaves the transaction active permits accidental later publication.',
['Can this rolled-back transaction commit?','No','Yes, if its map is empty','Only once'],'The active-state check rejects ended transactions.',
'Specify behavior for repeated rollback and repeated commit. Test that every ended transaction remains unable to publish.');
add('transactions','stale-commit','Reject a commit based on an old revision',
'Two candidates can begin from the same committed revision. Publishing one invalidates the other candidate’s base revision. A compare-before-publish check prevents the later stale candidate from silently overwriting the newer state.\n\nThis coarse whole-store validation rejects more cases than a fine-grained conflict detector, but its failure contract is easy to observe.',
cpp(th,"    Store store;\n    auto first = store.begin(), stale = store.begin();\n    first.rows.at(1) = 50;\n    store.commit(first);\n    stale.rows.at(2) = 80;\n    std::cout << \"stale=\" << !store.commit(stale) << \" retained=\" << store.rows.at(1)\n              << \",\" << store.rows.at(2) << \"\\n\";",tx),'stale=1 retained=50,20',
'The stale candidate is rejected in full. The newer value fifty survives and the stale update to key two is not published.',
'Checking a revision before an unlocked write does not prevent races in a real concurrent implementation; validation and publication need synchronization together.',
['What must be protected together in a concurrent implementation?','Revision validation and state publication','Only output formatting','Only candidate construction'],'The check must remain valid through publication.',
'Implement the same schedule with a mutex-protected store. Keep the stale-candidate rejection deterministic with explicit coordination.');
add('transactions','batch-invariant','Commit related fields as one logical unit',
'A transaction can preserve a compound invariant across several tentative updates. A transfer between two balances should publish both changes or neither, provided validation and arithmetic checks have succeeded.\n\nThe example uses small nonnegative values and a serialized commit. A real transfer API also needs insufficient-funds and overflow rejection before candidate mutation.',
cpp(th,"    Store store;\n    auto transaction = store.begin();\n    transaction.rows.at(1) -= 3;\n    transaction.rows.at(2) += 3;\n    store.commit(transaction);\n    std::cout << store.rows.at(1) << \"+\" << store.rows.at(2) << \"=\"\n              << store.rows.at(1) + store.rows.at(2) << \"\\n\";",tx),'7+23=30',
'The total is conserved while the individual balances change together at commit.',
'Atomic counters for individual balances do not automatically make the two-field transfer invariant atomic.',
['Which invariant should every committed transfer preserve?','The combined total, absent fees or external changes','Each individual balance is unchanged','The transaction map stays empty'],'The operation changes two fields while preserving their sum.',
'Reject an oversized transfer before changing either candidate balance. Test committed state after both rejection and success.');
add('transactions','commit-preparation-failure','Fallible preparation must precede publication',
'A commit can fail while validating or allocating a candidate. Arrange those operations before the nonthrowing publication step so failure leaves committed state unchanged.\n\nThis fixture injects a validation exception explicitly. It illustrates the commit ordering rather than relying on an unpredictable allocation failure.',
cpp(th,"    Store store;\n    auto transaction = store.begin();\n    transaction.rows.at(1) = -1;\n    try {\n        if (transaction.rows.at(1) < 0)\n            throw std::runtime_error(\"negative balance\");\n        store.commit(transaction);\n    } catch (const std::exception &error) {\n        std::cout << error.what() << \"\\n\";\n    }\n    std::cout << \"committed=\" << store.rows.at(1) << \" revision=\" << store.revision\n              << \"\\n\";",tx),'negative balance\ncommitted=10 revision=0',
'Validation fails before commit, so neither the committed value nor revision changes.',
'Catching an exception after publishing a partially prepared state cannot establish the strong guarantee retroactively.',
['Where must fallible validation occur?','Before publication','After increasing the revision','Only in the caller’s log formatter'],'The old committed state remains the fallback until preparation succeeds.',
'Inject failures at several preparation boundaries and compare committed bytes and revision with an independently captured before-state.');
add('transactions','transaction-lifecycle','Make begin, commit, and abort states explicit',
'A transaction lifecycle defines which operations are legal before and after completion. Reusing a completed candidate can otherwise replay old work against a new revision.\n\nThis model permits one successful commit per transaction. A failed stale commit remains active so the caller can inspect or discard it, but cannot succeed without a new begin under this API.',
cpp(th,"    Store store;\n    auto transaction = store.begin();\n    bool first = store.commit(transaction), second = store.commit(transaction);\n    std::cout << \"first=\" << first << \" second=\" << second\n              << \" revision=\" << store.revision << \"\\n\";",tx),'first=1 second=0 revision=1',
'The first commit ends the transaction. The second fails without advancing the store revision again.',
'An inactive flag that is never checked does not enforce a lifecycle contract.',
['How many successful commits can this candidate perform?','One','Unlimited','Two if no rows changed'],'Successful commit marks it inactive.',
'Write a small transition table for active, committed, and aborted states. Test each allowed and rejected transition explicitly.');

const wal="using Bytes = std::vector<unsigned char>;\nBytes record(unsigned char tag, unsigned char transaction, unsigned value) {\n    Bytes bytes{tag, transaction};\n    for (unsigned i = 0; i < 4; ++i)\n        bytes.push_back(static_cast<unsigned char>((value >> (i * 8)) & 255u));\n    unsigned char checksum = 0;\n    for (auto byte : bytes)\n        checksum ^= byte;\n    bytes.push_back(checksum);\n    return bytes;\n}\nvoid append(Bytes &log, const Bytes &bytes) {\n    log.insert(log.end(), bytes.begin(), bytes.end());\n}\nstruct Recovery {\n    unsigned value = 0;\n    std::size_t valid_bytes = 0;\n    bool tail = false;\n};\nRecovery recover(std::span<const unsigned char> log, unsigned initial = 0) {\n    Recovery result{initial, 0, false};\n    std::map<unsigned, unsigned> pending;\n    while (log.size() - result.valid_bytes >= 7) {\n        auto at = result.valid_bytes;\n        unsigned char checksum = 0;\n        for (unsigned i = 0; i < 6; ++i)\n            checksum ^= log[at + i];\n        auto tag = log[at], transaction = log[at + 1];\n        if (checksum != log[at + 6] || (tag != 'P' && tag != 'C'))\n            break;\n        unsigned value = 0;\n        for (unsigned i = 0; i < 4; ++i)\n            value |= unsigned(log[at + 2 + i]) << (i * 8);\n        if (tag == 'P')\n            pending[transaction] = value;\n        else if (auto found = pending.find(transaction); found != pending.end()) {\n            result.value = found->second;\n            pending.erase(found);\n        }\n        result.valid_bytes += 7;\n    }\n    result.tail = result.valid_bytes != log.size();\n    return result;\n}";
const wh='iostream map span vector';
add('wal-recovery','wal-records','Define a log record independently of memory layout',
'A redo record needs a documented encoding before recovery can interpret it. This bounded single-value model uses seven bytes: tag, transaction ID, four little-endian value bytes, and a one-byte XOR check.\n\nThe XOR check is a teaching integrity mechanism with collisions, not a production checksum or authentication primitive. The model does not implement a multi-row database log.',
cpp(wh,"    auto bytes = record('P', 1, 42);\n    std::cout << \"bytes=\" << bytes.size() << \" value-low=\" << unsigned(bytes[2])\n              << \"\\n\";",wal),'bytes=7 value-low=42',
'The value’s low byte is at offset two, and every encoded record has the same seven-byte size.',
'Writing a C++ struct directly would introduce padding and host-layout assumptions into recovery.',
['How is the value encoded?','Four explicit little-endian bytes','The native unsigned object representation','A pointer to a live value'],'The record layout is independent of the process object layout.',
'Write an independent seven-byte fixture for a known value. Document the check’s collision limits before choosing a production integrity algorithm.');
add('wal-recovery','wal-commit-marker','Recover only values with a complete commit marker',
'A complete update record is not evidence that its transaction committed. Recovery should retain tentative redo until a valid commit marker authorizes publication. Uncommitted tail work is ignored.\n\nThis model remembers one pending value per transaction ID. Transaction IDs are bounded fixture identifiers and are not reused across an unresolved transaction.',
cpp(wh,"    Bytes log;\n    append(log, record('P', 1, 42));\n    std::cout << \"before=\" << recover(log).value;\n    append(log, record('C', 1, 0));\n    std::cout << \" after=\" << recover(log).value << \"\\n\";",wal),'before=0 after=42',
'The update alone leaves the recovered committed value at zero. Adding the complete marker makes forty-two visible.',
'Applying every valid update record during recovery can expose transactions that never committed.',
['What authorizes publication in this model?','A complete valid commit marker','Any update tag','A successful allocation'],'Tentative redo is distinct from committed redo.',
'Append an uncommitted second transaction after the committed one. Check that recovery preserves only the committed value.');
add('wal-recovery','wal-torn-tail','A truncated final record is not a complete record',
'A crash can leave a log ending inside a record. Recovery scans only complete validated records and reports that bytes remain after the accepted prefix. It must not synthesize missing bytes from zero-filled memory.\n\nThis is a prefix-recovery model; it does not claim that arbitrary storage-device damage obeys a simple prefix failure model.',
cpp(wh,"    Bytes log;\n    append(log, record('P', 1, 42));\n    auto commit = record('C', 1, 0);\n    log.insert(log.end(), commit.begin(), commit.end() - 1);\n    auto result = recover(log);\n    std::cout << \"value=\" << result.value << \" valid=\" << result.valid_bytes\n              << \" tail=\" << result.tail << \"\\n\";",wal),'value=0 valid=7 tail=1',
'The update is accepted into tentative state, but the six-byte commit prefix cannot authorize publication.',
'Continuing past a malformed record without a resynchronization contract can misinterpret payload bytes as new records.',
['Is a six-byte commit prefix sufficient?','No','Yes, because its tag is present','Only if the file size is even'],'The fixed record and its check must be complete.',
'Enumerate every truncation point of the update and commit pair. Specify the expected committed value for each prefix.');
add('wal-recovery','wal-corrupt-record','Stop at an invalid integrity boundary',
'Recovery should validate a record before applying its meaning. A changed byte can invalidate the record’s integrity check, forcing a stop at the earlier accepted prefix.\n\nA one-byte XOR check detects this fixture’s single-bit change but not every possible corruption. Distinguish a demonstration of validation ordering from a claim about production error-detection strength.',
cpp(wh,"    Bytes log;\n    append(log, record('P', 1, 42));\n    append(log, record('C', 1, 0));\n    log[2] ^= 1;\n    auto result = recover(log);\n    std::cout << \"valid=\" << result.valid_bytes << \" value=\" << result.value\n              << \" tail=\" << result.tail << \"\\n\";",wal),'valid=0 value=0 tail=1',
'The first record fails its check, so neither it nor later records are interpreted under an unsupported resynchronization assumption.',
'A checksum that detects some errors is not proof that all corruption or adversarial edits are detected.',
['When is a record applied?','After its complete encoding validates','Before checking its final byte','Whenever its tag looks familiar'],'Validation precedes state effects.',
'Create a two-byte change that preserves XOR to demonstrate the limit. Keep that limitation visible when replacing the teaching check with a stronger one.');
add('wal-recovery','wal-interleaving','Associate redo with the correct transaction',
'Interleaved update records need transaction identity so one transaction’s commit does not publish another’s pending state. Recovery groups tentative values by transaction ID before processing commit markers.\n\nThe fixture is serialized log interpretation, not concurrent file writing. The writer side still needs an ordering and synchronization contract.',
cpp(wh,"    Bytes log;\n    append(log, record('P', 1, 10));\n    append(log, record('P', 2, 20));\n    append(log, record('C', 1, 0));\n    std::cout << \"committed=\" << recover(log).value << \"\\n\";",wal),'committed=10',
'Transaction two remains pending while transaction one’s committed value becomes visible.',
'One global pending slot would let the second update overwrite the state associated with the first transaction’s marker.',
['Which value does transaction one’s marker publish?','Its own pending value ten','The most recent update from any transaction','Both values at once'],'Recovery retains pending state by transaction identity.',
'Commit transaction two afterward and check the new visible value. Define and reject unsupported transaction-ID reuse.');
add('wal-recovery','wal-idempotence','Redo should tolerate repeating already applied work',
'Recovery may run more than once. Redo records that assign a known value are naturally idempotent: applying the same assignment again does not increment it twice. Other operation forms need explicit sequence or applied-position checks.\n\nThis one-value fixture demonstrates assignment redo. It does not establish idempotence for arbitrary user-defined operations.',
cpp(wh,"    Bytes log;\n    append(log, record('P', 1, 42));\n    append(log, record('C', 1, 0));\n    auto first = recover(log);\n    auto second = recover(log, first.value);\n    std::cout << first.value << \" \" << second.value << \"\\n\";",wal),'42 42',
'Replaying from a state already holding forty-two leaves the same committed value.',
'An unchecked “add five” redo can apply the same logical change twice after repeated recovery.',
['Why is this redo repeatable?','It assigns a known final value','It runs only once by definition','The checksum removes repeated records'],'Repeating the assignment has the same state effect.',
'Model an increment redo and show its repeated-recovery failure. Add an applied log-position rule before claiming general idempotence.');
add('wal-recovery','wal-crash-prefix-oracle','Enumerate crash prefixes against a committed-state oracle',
'A finite crash-prefix workload can test every byte truncation of a small log fixture. The expected state comes from the documented commit boundary rather than the recovery parser’s own logic.\n\nThis check is valuable but limited: real crashes, reordering, sector behavior, and torn writes need a larger host failure model.',
cpp(wh,"    Bytes log;\n    append(log, record('P', 1, 42));\n    append(log, record('C', 1, 0));\n    bool valid = true;\n    for (std::size_t length = 0; length <= log.size(); ++length) {\n        auto state = recover(std::span(log).first(length));\n        valid = valid && (state.value == (length == 14 ? 42u : 0u));\n    }\n    std::cout << \"prefixes=\" << log.size() + 1 << \" verified=\" << valid << \"\\n\";\n    return valid ? 0 : 1;",wal),'prefixes=15 verified=1',
'All fifteen prefixes agree with an independent rule: only the complete fourteen-byte pair commits forty-two.',
'Passing prefix tests is not evidence that the underlying filesystem guarantees prefix-only failures.',
['Where does the expected commit boundary come from?','The independently specified record contract','Calling recover a second time','The wall-clock duration'],'The oracle does not duplicate the parser’s transitions.',
'Extend to two transactions and compute expected states at every complete commit boundary. Preserve raw failing prefixes for debugging.');
add('wal-recovery','wal-native-sync','Separate checked writes from a host durability request',
'A successful write or stream close does not by itself promise power-loss durability. A native host adapter can request synchronization and must check that request’s result before reporting the corresponding durability boundary.\n\nThis POSIX investigation writes one byte, checks fsync, and checks close. It demonstrates syscall handling, not a full WAL-plus-directory publication protocol or device-failure proof.',
cpp('fcntl.h iostream unistd.h',"    int fd = ::open(\"redo.log\", O_WRONLY | O_CREAT | O_TRUNC, 0600);\n    if (fd < 0)\n        return 1;\n    const char byte = 'x';\n    bool written = ::write(fd, &byte, 1) == 1;\n    bool synced = written && ::fsync(fd) == 0;\n    bool closed = ::close(fd) == 0;\n    std::cout << \"write=\" << written << \" sync=\" << synced << \" close=\" << closed\n              << \"\\n\";\n    return written && synced && closed ? 0 : 1;"),'write=1 sync=1 close=1',
'The success line requires all three host calls to report success. Publication of a renamed checkpoint would add further ordering and directory concerns.',
'Ignoring fsync failure and printing “durable” misstates the host result.',
['Does this finite run prove power-loss durability on every device?','No','Yes','Only because the file contains one byte'],'It verifies checked behavior on the selected host, under its documented assumptions.',
'Wrap the descriptor in RAII and inject write/sync failures through an adapter. Document when a commit acknowledgement is allowed.',{native:true,reason:'POSIX file synchronization requires a native host.'});

add('query-planning','plan-cost','Compare candidate access paths under a stated model',
'A planner compares estimated costs for access paths that produce the same logical candidates. A simple model can count scan row visits versus index traversal plus fetched matches. The units and assumptions must be stated before comparing numbers.\n\nThis fixture treats one counted operation as one model unit; it is not a hardware latency prediction.',
cpp('iostream',"    unsigned rows = 1000, height = 3, matches = 4;\n    unsigned scan = rows, index = height + matches;\n    std::cout << \"scan=\" << scan << \" index=\" << index\n              << \" choose=\" << (index < scan ? \"index\" : \"scan\") << \"\\n\";"),'scan=1000 index=7 choose=index',
'The selective lookup visits far fewer modeled units than scanning all rows.',
'Comparing row counts with milliseconds without a conversion model gives meaningless costs.',
['What makes the two costs comparable here?','They use the same explicitly chosen model unit','Both variables are unsigned','The index has a shorter name'],'A cost model must define common units and relevant work.',
'Add per-page fetch and sequential-scan weights. State which observations would justify those weights.');
add('query-planning','plan-selectivity','Selectivity changes the cost of an index lookup',
'An index is most useful when it eliminates substantial work. If nearly every row matches and each index result requires a separate fetch, a scan can become cheaper under the chosen model.\n\nSelectivity is a workload property, not an invariant of the index data structure. Estimate it from appropriate statistics and validate estimates against actual candidate counts.',
cpp('iostream',"    for (unsigned matches : {4u, 1000u}) {\n        unsigned scan = 1000, index = 3 + 2 * matches;\n        std::cout << matches << \":\" << (index < scan ? \"index\" : \"scan\") << \"\\n\";\n    }"),'4:index\n1000:scan',
'Four matches favor the index; a thousand modeled two-unit fetches favor scanning.',
'Choosing an index merely because one exists ignores selectivity and access costs.',
['Can a full-table match favor a scan?','Yes','No, indexes are always faster','Only if the key type is a string'],'An index can add traversal and fetch work when little is filtered out.',
'Find the crossover point in this model and test values on either side. Compare the prediction with a separately instrumented executor.');
add('query-planning','plan-statistics','Stale statistics can select a poor plan',
'Statistics summarize a particular data distribution. After inserts, deletes, or skewed updates, an old estimate may no longer represent the current workload. Track estimate and observation separately so errors are visible.\n\nThis lesson reports an estimation error directly instead of pretending one small sample proves a permanent distribution.',
cpp('iostream',"    unsigned estimated_matches = 5, observed_matches = 500;\n    std::cout << \"estimated=\" << estimated_matches << \" observed=\" << observed_matches\n              << \" ratio=\" << observed_matches / estimated_matches << \"\\n\";"),'estimated=5 observed=500 ratio=100',
'The actual candidate count is one hundred times the estimate, indicating the model needs attention.',
'A statistics refresh policy needs a workload trigger; silently assuming uniform data can hide skew.',
['Should estimates be confused with actual counts?','No','Yes','Only when both are integers'],'Statistics are predictions that must be compared with observations.',
'Create a skewed key distribution and compare a uniform estimate with measured equality counts. Define a refresh trigger.');
add('query-planning','covering-index','Projection can change whether row fetches are needed',
'An index can cover a query when it already contains every requested field. A covering path can avoid fetching base rows, changing its cost compared with an index that stores only keys.\n\nCoverage depends on the query projection and the index’s stored payload. It is not a universal property of all queries using that index.',
cpp('iostream',"    unsigned height = 3, matches = 8;\n    std::cout << \"covered=\" << height + matches << \" fetch=\" << height + 3 * matches\n              << \"\\n\";"),'covered=11 fetch=27',
'The model adds no base-row fetch cost to the covered path and adds two extra units per match to the fetching path.',
'Reading an unstored column from an index entry invents data rather than providing coverage.',
['What determines coverage?','The requested fields and index payload','Only the number of matching keys','The compiler optimization level'],'Every projected field must be available from the chosen path.',
'List columns for several projections and decide which are covered by an (id,score) index. Keep name fetches explicit.');
add('query-planning','explain-plan','Explain estimates and validate result equivalence',
'An explain representation should name the chosen access path, predicate, ordering, and estimated work. It helps a reader understand why a planner made a choice and which assumptions to challenge.\n\nPlan selection must not change query meaning. A scan plan and an index plan should agree on result rows under an independent fixture even when their work differs.',
cpp('iostream string',"    Plan plan{\"index(id)\", 3, 2};\n    std::cout << plan.path\n              << \" predicate=id=7 estimated=\" << plan.traversal + plan.matches << \"\\n\";","struct Plan {\n    std::string path;\n    unsigned traversal, matches;\n};"),'index(id) predicate=id=7 estimated=5',
'The output exposes the path and the two sources of estimated work rather than claiming an unexplained speedup.',
'An explain string is not a substitute for checking the executor’s actual rows and observed work.',
['What must remain the same across legal plan choices?','The query’s logical result','The number of page fetches','The internal operator names'],'Optimization may change work but must preserve semantics.',
'Execute a scan and a lookup on the same fixed table, compare results, and print estimated versus observed candidate counts.');
}
